import{_ as n,o as a,c as s,ag as l}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"Agent 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"AI/agent.md","filePath":"AI/agent.md"}'),e={name:"AI/agent.md"};function r(o,t,i,g,p,d){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="agent-是什么" tabindex="-1">Agent 是什么 <a class="header-anchor" href="#agent-是什么" aria-label="Permalink to &quot;Agent 是什么&quot;">​</a></h1><p>大模型擅长理解和生成文本，但默认只会「一问一答」。<strong>Agent（智能体）</strong> 指的是：在模型之上，再加一层能<strong>规划、调用工具、根据结果继续行动</strong>的运行时，让它朝目标持续推进，而不是只回一句漂亮话。</p><p>可以粗记成：</p><blockquote><p><strong>模型 = 脑子，Agent = 会用工具、会按步骤做事的执行者。</strong></p></blockquote><h2 id="和普通聊天有什么区别" tabindex="-1">和普通聊天有什么区别 <a class="header-anchor" href="#和普通聊天有什么区别" aria-label="Permalink to &quot;和普通聊天有什么区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>普通对话（Chat）</th><th>Agent</th></tr></thead><tbody><tr><td><strong>交互形态</strong></td><td>用户问 → 模型答，多半一轮结束</td><td>用户给目标 → Agent 多步执行直到完成或失败</td></tr><tr><td><strong>能否碰外部世界</strong></td><td>一般不能（除非产品内置了固定插件）</td><td>可以读文件、跑命令、调 API、查库等</td></tr><tr><td><strong>中间过程</strong></td><td>通常不可见或很少</td><td>常有计划、工具调用、观察结果、再决策的循环</td></tr><tr><td><strong>失败处理</strong></td><td>再问一句重试</td><td>可按流程回退、换策略、请求确认</td></tr></tbody></table><p>一句话：<strong>Chat 偏回答问题，Agent 偏完成任务。</strong></p><h2 id="agent-常见构成" tabindex="-1">Agent 常见构成 <a class="header-anchor" href="#agent-常见构成" aria-label="Permalink to &quot;Agent 常见构成&quot;">​</a></h2><p>不同产品叫法不一，但骨架往往类似：</p><ol><li><strong>目标 / 任务</strong>：用户要达成什么（修 bug、写周报、查天气再总结）</li><li><strong>大脑（LLM）</strong>：理解意图、选下一步、组织最终回复</li><li><strong>工具（Tools）</strong>：真正动手的能力——本地命令、浏览器、GitHub、内部 RPC 等</li><li><strong>记忆 / 上下文</strong>：当前对话、打开的文件、历史工具结果、长期笔记等</li><li><strong>编排循环（Loop）</strong>：思考 → 行动 → 观察 → 再思考，直到结束条件满足</li></ol><p>最常见的一种循环叫 <strong>ReAct</strong>（Reason + Act）：先推理该做什么，再调用工具，再根据观察继续。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户目标</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[思考] 下一步该干什么？</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[行动] 调用工具 / 改文件 / 提问确认</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[观察] 拿到结果或报错</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>完成？──否──→ 回到思考</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>  是</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>输出结论</span></span></code></pre></div><h2 id="和-skill、mcp-的关系" tabindex="-1">和 Skill、MCP 的关系 <a class="header-anchor" href="#和-skill、mcp-的关系" aria-label="Permalink to &quot;和 Skill、MCP 的关系&quot;">​</a></h2><p>在 Cursor、Claude Code 这类产品里，这三个词经常一起出现，职责不同：</p><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>整套「能多步完成任务」的运行时 / 产品形态</td></tr><tr><td><strong>Skill</strong></td><td>教 Agent 按什么流程做事（规范与步骤）</td></tr><tr><td><strong>MCP</strong></td><td>给 Agent 接上外部工具与数据的标准协议</td></tr></tbody></table><p>关系可以记成：</p><ul><li>Agent 是<strong>谁在干活</strong></li><li>Skill 是<strong>怎么干</strong>（流程）</li><li>MCP 是<strong>能干哪些外部的事</strong>（手脚）</li></ul><p>更细的对比见：<a href="./skill-vs-mcp.html">Skill 与 MCP 异同</a>；Skill / MCP 专题见：<a href="./skill.html">Skill</a>、<a href="./mcp.html">MCP</a>。</p><h2 id="常见形态" tabindex="-1">常见形态 <a class="header-anchor" href="#常见形态" aria-label="Permalink to &quot;常见形态&quot;">​</a></h2><p>按使用方式粗分：</p><ul><li><strong>对话式 Agent</strong>：在聊天窗里给目标，例如 Cursor Agent、Claude 的 Agent 模式</li><li><strong>IDE 内嵌 Agent</strong>：和编辑器、终端、Git 深度结合，改代码并跑验证</li><li><strong>自主 / 后台 Agent</strong>：少交互、长时间跑任务（需更强权限与护栏）</li><li><strong>多 Agent</strong>：拆成「规划 / 编码 / 评审」等角色协作（工程更复杂，不是入门必选项）</li></ul><p>入门阶段先掌握「单 Agent + 工具调用循环」足够。</p><h2 id="能力边界与风险" tabindex="-1">能力边界与风险 <a class="header-anchor" href="#能力边界与风险" aria-label="Permalink to &quot;能力边界与风险&quot;">​</a></h2><p>Agent 变强，风险也变大：</p><ul><li><strong>权限过大</strong>：能删文件、推远程、调生产接口时，误操作代价高</li><li><strong>幻觉仍在</strong>：模型可能编造路径、命令或结论，需要验证步骤</li><li><strong>循环失控</strong>：反复无效重试，耗时耗钱；要有步数/超时上限</li><li><strong>上下文膨胀</strong>：工具结果塞太多，反而选错下一步</li></ul><p>落地建议：</p><ul><li>危险操作要确认或走 Skill 里的硬约束</li><li>关键任务固定「改完必须跑测试 / 检查清单」</li><li>工具权限按最小必要原则开通（尤其是 MCP Server）</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>Agent</strong> = 模型 + 工具 + 多步编排，目标是<strong>完成任务</strong>而不只是聊天</li><li>核心循环是：<strong>思考 → 行动 → 观察 → 再决策</strong></li><li>工程上用 <strong>Skill</strong> 管流程，用 <strong>MCP</strong> 管外部连接，两者都挂在 Agent 之上</li></ul>`,29)])])}const u=n(e,[["render",r]]);export{c as __pageData,u as default};
